CREATE TABLE atlys_dataset.forex_purchased (`id` FixedString(32) COMMENT 'event id, high cardinality' CODEC(ZSTD(1)), `timestamp` DateTime64(3, 'UTC') COMMENT 'event time, ms precision' CODEC(Delta(8), ZSTD(1)), `device_type` LowCardinality(String) COMMENT 'ios/android/web-user-b2c/Desktop, 4 values', `os` LowCardinality(String) DEFAULT '' COMMENT 'os name; 5.9% empty, bucket as unknown', `app_version` LowCardinality(String) COMMENT 'client app version, 3 values', `geoip_country_code` LowCardinality(String) COMMENT 'geo country from IP, 7 values', `city` LowCardinality(String) COMMENT 'geo city from IP, 7 values', `client_lib` LowCardinality(String) COMMENT 'mobile-rn or web-js', `user_id` String COMMENT 'traveller id, 28 chars, joins all tables' CODEC(ZSTD(1)), `application_id` FixedString(32) COMMENT 'links funnel stages for this journey' CODEC(ZSTD(1)), `destination` LowCardinality(String) COMMENT 'trip destination ISO-2, 14 values, PM cut', `from_currency` LowCardinality(String) COMMENT 'always INR, never aggregate across currencies', `to_currency` LowCardinality(String) COMMENT 'destination currency, 13 values', `amount` Decimal(18, 2) COMMENT 'INR amount, 6 distinct values 200-1500' CODEC(T64, ZSTD(1)), `addon_value_inr` Decimal(18, 2) COMMENT 'add-on order value INR paid, range 4245-130911' CODEC(T64, ZSTD(1))) ENGINE = SharedMergeTree('/clickhouse/tables/{uuid}/{shard}', '{replica}') PARTITION BY toYYYYMM(timestamp) ORDER BY (device_type, destination, application_id, timestamp) SETTINGS index_granularity = 8192 COMMENT 'forex_purchased: forex paid for; funnel conversion event, endpoint of attach-rate calc from offer_shown'
CREATE TABLE atlys_dataset.forex_offer_shown (`id` FixedString(32) COMMENT 'event id, high cardinality' CODEC(ZSTD(1)), `timestamp` DateTime64(3, 'UTC') COMMENT 'event time, ms precision' CODEC(Delta(8), ZSTD(1)), `device_type` LowCardinality(String) COMMENT 'ios/android/web-user-b2c/Desktop, 4 values', `os` LowCardinality(String) DEFAULT '' COMMENT 'os name; 6.1% empty, bucket as unknown', `app_version` LowCardinality(String) COMMENT 'client app version, 3 values', `geoip_country_code` LowCardinality(String) COMMENT 'geo country from IP, 7 values', `city` LowCardinality(String) COMMENT 'geo city from IP, 7 values', `client_lib` LowCardinality(String) COMMENT 'mobile-rn or web-js', `user_id` String COMMENT 'traveller id, 28 chars, joins all tables' CODEC(ZSTD(1)), `application_id` FixedString(32) COMMENT 'links funnel stages for this journey' CODEC(ZSTD(1)), `destination` LowCardinality(String) COMMENT 'trip destination ISO-2, 14 values, PM cut', `from_currency` LowCardinality(String) COMMENT 'always INR, never aggregate across currencies', `to_currency` LowCardinality(String) COMMENT 'destination currency, 13 values', `fx_rate` Float64 COMMENT 'offered INR rate, range 0.0379-89.9827' CODEC(ZSTD(1))) ENGINE = SharedMergeTree('/clickhouse/tables/{uuid}/{shard}', '{replica}') PARTITION BY toYYYYMM(timestamp) ORDER BY (device_type, destination, application_id, timestamp) SETTINGS index_granularity = 8192 COMMENT 'forex_offer_shown: offer renders at checkout; funnel step 1 of Instant Forex Add-on'
CREATE TABLE atlys_dataset.forex_added_to_cart (`id` FixedString(32) COMMENT 'event id, high cardinality' CODEC(ZSTD(1)), `timestamp` DateTime64(3, 'UTC') COMMENT 'event time, ms precision' CODEC(Delta(8), ZSTD(1)), `device_type` LowCardinality(String) COMMENT 'ios/android/web-user-b2c/Desktop, 4 values', `os` LowCardinality(String) DEFAULT '' COMMENT 'os name; 5.9% empty, bucket as unknown', `app_version` LowCardinality(String) COMMENT 'client app version, 3 values', `geoip_country_code` LowCardinality(String) COMMENT 'geo country from IP, 7 values', `city` LowCardinality(String) COMMENT 'geo city from IP, 7 values', `client_lib` LowCardinality(String) COMMENT 'mobile-rn or web-js', `user_id` String COMMENT 'traveller id, 28 chars, joins all tables' CODEC(ZSTD(1)), `application_id` FixedString(32) COMMENT 'links funnel stages for this journey' CODEC(ZSTD(1)), `destination` LowCardinality(String) COMMENT 'trip destination ISO-2, 14 values, PM cut', `from_currency` LowCardinality(String) COMMENT 'always INR, never aggregate across currencies', `to_currency` LowCardinality(String) COMMENT 'destination currency, 13 values', `amount` Decimal(18, 2) COMMENT 'INR amount, 6 distinct values 200-1500' CODEC(T64, ZSTD(1)), `addon_value_inr` Decimal(18, 2) COMMENT 'add-on order value INR, range 4135-134453, AOV metric' CODEC(T64, ZSTD(1))) ENGINE = SharedMergeTree('/clickhouse/tables/{uuid}/{shard}', '{replica}') PARTITION BY toYYYYMM(timestamp) ORDER BY (device_type, destination, application_id, timestamp) SETTINGS index_granularity = 8192 COMMENT 'forex_added_to_cart: forex added to order; funnel step 4, precedes purchase for attach-rate math'
CREATE TABLE atlys_dataset.currency_selected (`id` FixedString(32) COMMENT 'event id, high cardinality' CODEC(ZSTD(1)), `timestamp` DateTime64(3, 'UTC') COMMENT 'event time, ms precision' CODEC(Delta(8), ZSTD(1)), `device_type` LowCardinality(String) COMMENT 'ios/android/web-user-b2c/Desktop, 4 values', `os` LowCardinality(String) DEFAULT '' COMMENT 'os name; 6.3% empty, bucket as unknown', `app_version` LowCardinality(String) COMMENT 'client app version, 3 values', `geoip_country_code` LowCardinality(String) COMMENT 'geo country from IP, 7 values', `city` LowCardinality(String) COMMENT 'geo city from IP, 7 values', `client_lib` LowCardinality(String) COMMENT 'mobile-rn or web-js', `user_id` String COMMENT 'traveller id, 28 chars, joins all tables' CODEC(ZSTD(1)), `application_id` FixedString(32) COMMENT 'links funnel stages for this journey' CODEC(ZSTD(1)), `destination` LowCardinality(String) COMMENT 'trip destination ISO-2, 14 values, PM cut', `from_currency` LowCardinality(String) COMMENT 'always INR, never aggregate across currencies', `to_currency` LowCardinality(String) COMMENT 'destination currency, 13 values') ENGINE = SharedMergeTree('/clickhouse/tables/{uuid}/{shard}', '{replica}') PARTITION BY toYYYYMM(timestamp) ORDER BY (device_type, destination, application_id, timestamp) SETTINGS index_granularity = 8192 COMMENT 'currency_selected: user engages with currency; funnel step 2 of Instant Forex Add-on'
CREATE TABLE atlys_dataset.amount_entered (`id` FixedString(32) COMMENT 'event id, high cardinality' CODEC(ZSTD(1)), `timestamp` DateTime64(3, 'UTC') COMMENT 'event time, ms precision' CODEC(Delta(8), ZSTD(1)), `device_type` LowCardinality(String) COMMENT 'ios/android/web-user-b2c/Desktop, 4 values', `os` LowCardinality(String) DEFAULT '' COMMENT 'os name; 6.3% empty, bucket as unknown', `app_version` LowCardinality(String) COMMENT 'client app version, 3 values', `geoip_country_code` LowCardinality(String) COMMENT 'geo country from IP, 7 values', `city` LowCardinality(String) COMMENT 'geo city from IP, 7 values', `client_lib` LowCardinality(String) COMMENT 'mobile-rn or web-js', `user_id` String COMMENT 'traveller id, 28 chars, joins all tables' CODEC(ZSTD(1)), `application_id` FixedString(32) COMMENT 'links funnel stages for this journey' CODEC(ZSTD(1)), `destination` LowCardinality(String) COMMENT 'trip destination ISO-2, 14 values, PM cut', `from_currency` LowCardinality(String) COMMENT 'always INR, never aggregate across currencies', `to_currency` LowCardinality(String) COMMENT 'destination currency, 13 values', `amount` Decimal(18, 2) COMMENT 'INR amount entered, 6 distinct values 200-1500' CODEC(T64, ZSTD(1))) ENGINE = SharedMergeTree('/clickhouse/tables/{uuid}/{shard}', '{replica}') PARTITION BY toYYYYMM(timestamp) ORDER BY (device_type, destination, application_id, timestamp) SETTINGS index_granularity = 8192 COMMENT 'amount_entered: user enters an amount; funnel step 3, drop-off vs offer_shown metric'